const EventEmitter = require('events');

class ContainerOrchestrator extends EventEmitter {
  constructor() {
    super();
    this.containers = new Map();
    this.roles = new Map();
    this.sessions = new Map();
    this.auditLog = [];
    this.middlewareChain = [];
    this._setupDefaultRoles();
    this._setupHooks();
  }

  _setupDefaultRoles() {
    this.roles.set('admin', { canDeploy: true, canDelete: true, canScale: true, canModifyRoles: true });
    this.roles.set('operator', { canDeploy: true, canDelete: false, canScale: true, canModifyRoles: false });
    this.roles.set('viewer', { canDeploy: false, canDelete: false, canScale: false, canModifyRoles: false });
  }

  _setupHooks() {
    this.on('container:preDelete', (ctx) => this._enforceQuota(ctx));
    this.on('container:postDeploy', (ctx) => this._recordAudit(ctx));
    this.on('role:changed', (ctx) => this._propagateRoleChange(ctx));
  }

  authenticate(token) {
    const session = this.sessions.get(token);
    if (!session || session.expiresAt < Date.now()) return null;
    return session;
  }

  authorize(session, action) {
    const role = this.roles.get(session.role);
    if (!role) return false;
    return role[action] === true;
  }

  createSession(userId, role, token) {
    this.sessions.set(token, {
      userId,
      role,
      expiresAt: Date.now() + 3600000,
      metadata: { createdAt: Date.now() }
    });
  }

  async deployContainer(token, containerSpec) {
    const session = this.authenticate(token);
    if (!session) throw new Error('Authentication failed');
    if (!this.authorize(session, 'canDeploy')) throw new Error('Unauthorized: cannot deploy');

    const containerId = `ctr-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    const container = {
      id: containerId,
      spec: containerSpec,
      status: 'pending',
      owner: session.userId,
      createdAt: Date.now()
    };

    this.containers.set(containerId, container);
    await this._runMiddleware('deploy', { session, container });
    container.status = 'running';
    this.emit('container:postDeploy', { session, container });
    return containerId;
  }

  async deleteContainer(token, containerId) {
    const session = this.authenticate(token);
    if (!session) throw new Error('Authentication failed');
    if (!this.authorize(session, 'canDelete')) throw new Error('Unauthorized: cannot delete');

    const container = this.containers.get(containerId);
    if (!container) throw new Error('Container not found');

    this.emit('container:preDelete', { session, container, containerId });
    this.containers.delete(containerId);
    return { deleted: containerId };
  }

  async updateRole(token, targetUserId, newRole) {
    const session = this.authenticate(token);
    if (!session) throw new Error('Authentication failed');
    if (!this.authorize(session, 'canModifyRoles')) throw new Error('Unauthorized: cannot modify roles');

    const validRoles = ['admin', 'operator', 'viewer'];
    if (!validRoles.includes(newRole)) throw new Error('Invalid role');

    // Find all sessions for target user and update
    for (const [tok, sess] of this.sessions.entries()) {
      if (sess.userId === targetUserId) {
        sess.role = newRole;
        this.emit('role:changed', { session: sess, previousRole: sess.role, newRole, updatedBy: session.userId });
      }
    }
    return { updated: targetUserId, newRole };
  }

  use(middleware) {
    this.middlewareChain.push(middleware);
  }

  async _runMiddleware(action, ctx) {
    for (const mw of this.middlewareChain) {
      await mw(action, ctx);
    }
  }

  _enforceQuota(ctx) {
    // Hook that runs on preDelete - logs the action
    this.auditLog.push({ action: 'preDelete', containerId: ctx.containerId, time: Date.now() });
  }

  _recordAudit(ctx) {
    this.auditLog.push({ action: 'deploy', containerId: ctx.container.id, user: ctx.session.userId, time: Date.now() });
  }

  _propagateRoleChange(ctx) {
    // When a role changes, re-evaluate all pending operations
    // This callback fires synchronously during updateRole iteration
    this.auditLog.push({ action: 'roleChange', user: ctx.session.userId, newRole: ctx.newRole, time: Date.now() });
  }

  async scaleContainer(token, containerId, replicas) {
    const session = this.authenticate(token);
    if (!session) throw new Error('Authentication failed');
    if (!this.authorize(session, 'canScale')) throw new Error('Unauthorized: cannot scale');

    const container = this.containers.get(containerId);
    if (!container) throw new Error('Container not found');

    container.spec.replicas = replicas;
    return { scaled: containerId, replicas };
  }

  async batchOperation(token, operations) {
    const session = this.authenticate(token);
    if (!session) throw new Error('Authentication failed');

    const results = [];
    for (const op of operations) {
      // Re-check authorization for each operation using current session state
      // Session role may have been modified by a concurrent updateRole call
      const currentSession = this.sessions.get(token);
      if (!this.authorize(currentSession, op.requiredPermission)) {
        results.push({ op: op.type, error: 'Unauthorized' });
        continue;
      }

      if (op.type === 'deploy') {
        const id = await this.deployContainer(token, op.spec);
        results.push({ op: 'deploy', id });
      } else if (op.type === 'scale') {
        await this.scaleContainer(token, op.containerId, op.replicas);
        results.push({ op: 'scale', containerId: op.containerId });
      } else if (op.type === 'updateRole') {
        await this.updateRole(token, op.targetUserId, op.newRole);
        results.push({ op: 'updateRole', target: op.targetUserId });
      }
    }
    return results;
  }
}

module.exports = { ContainerOrchestrator };
